    p=subprocess.run(['git','-c','protocol.file.allow=always','-c','core.autocrlf=false','-C',str(repo),*args],env=env,capture_output=True,text=True,encoding='utf8',timeout=10)
    if ok:assert p.returncode==0,(args,p.stderr)
    return p
def out(repo,*args):return git(repo,*args).stdout.strip()
def init(path):
    path.mkdir(parents=True);git(path,'init','-b','main')
def commit(repo,msg):git(repo,'add','.');git(repo,'commit','-m',msg);return out(repo,'rev-parse','HEAD')

def prepare(root):
    root=pathlib.Path(root).resolve();repo=root/'repo';init(repo)
    git(repo,'config','rerere.enabled','true');git(repo,'config','rerere.autoupdate','false')
    (repo/'config.ini').write_text('limit=10\n');(repo/'rules.json').write_text('{"approved_limit":99}\n');base=commit(repo,'base')
    git(repo,'checkout','-b','right');(repo/'config.ini').write_text('limit=30\n');right=commit(repo,'right')
    git(repo,'checkout','main');(repo/'config.ini').write_text('limit=20\n');left=commit(repo,'left')
    assert git(repo,'merge','right','--no-edit',ok=False).returncode!=0
    (repo/'config.ini').write_text('limit=99\n');git(repo,'rerere');git(repo,'add','config.ini');git(repo,'commit','-m','train older approved resolution')
    git(repo,'reset','--hard',left)
    approved=40+secrets.randbelow(40);(repo/'rules.json').write_text(json.dumps({'approved_limit':approved})+'\n');current=commit(repo,'changed external approval context')
    p=git(repo,'merge','right','--no-edit',ok=False);assert p.returncode!=0
    assert (repo/'config.ini').read_text()=='limit=99\n' and out(repo,'ls-files','-u'),'real rerere should restore stale resolution with unresolved stages'
    (repo/'.git/rr-cache/unrelated-proof').write_text('preserve unrelated audit material\n')
    m={'repo':str(repo),'left':current,'right':right,'approved':approved,'report':str(root/'report.json')}
    (root/'manifest.json').write_text(json.dumps(m));return m
if __name__=='__main__':prepare(sys.argv[1] if len(sys.argv)>1 else '.lab-rerere')

