import json,os,pathlib,sys,tempfile,time
def stat(path):
    text=path.read_text();fields=text.rsplit(')',1)[1].split()
    return fields[0],int(fields[19])
def sample(base):
    values={}
    for item in (base/'task').iterdir():
        tid=int(item.name);state,_=stat(item/'stat')
        values[tid]={'name':(item/'comm').read_text().rstrip('\n'),'state':state,'cpu':int((item/'schedstat').read_text().split()[0])}
    return values
def inspect(pid,interval):
    if not 0.2<=interval<=0.5:raise ValueError('interval must be 0.2..0.5 seconds')
    if not pid.isdecimal() or int(pid)<=0:raise ValueError('positive PID required')
    base=pathlib.Path('/proc')/str(int(pid));_,start=stat(base/'stat')
    first=sample(base);begin=time.monotonic_ns();time.sleep(interval);second=sample(base);end=time.monotonic_ns()
    if stat(base/'stat')[1]!=start or set(first)!=set(second):raise ValueError('process identity or thread set changed; retry')
    rows=[]
    for tid in sorted(first):
        delta=second[tid]['cpu']-first[tid]['cpu']
        if delta<0:raise ValueError('invalid counter regression')
        rows.append({'tid':tid,'name':second[tid]['name'],'state_before':first[tid]['state'],'state_after':second[tid]['state'],'cpu_ns_delta':delta})
    return {'pid':int(pid),'starttime':start,'interval_ns':end-begin,'threads':rows,'busiest_tid':max(rows,key=lambda row:row['cpu_ns_delta'])['tid']}
def main():
    result=inspect(sys.argv[1],float(sys.argv[2]));target=pathlib.Path(sys.argv[3]);tmp=None
    try:
        with tempfile.NamedTemporaryFile(mode='w',encoding='utf8',dir=target.parent,delete=False) as f:
            tmp=pathlib.Path(f.name);json.dump(result,f)
        os.replace(tmp,target)
    finally:
        if tmp is not None and tmp.exists():tmp.unlink()
if __name__=='__main__':
    try:main()
    except Exception as exc:print(str(exc),file=sys.stderr);sys.exit(1)
