import os,pathlib,shutil,stat,subprocess,tempfile
def regular(path):
    if not stat.S_ISREG(os.lstat(path).st_mode):raise ValueError('regular non-symlink file required')
def publish(source,target,reader_uid):
    source=pathlib.Path(source);target=pathlib.Path(target)
    if type(reader_uid) is not int or not 0<=reader_uid<2**32-1 or reader_uid==os.geteuid():raise ValueError('distinct valid numeric reader UID required')
    regular(source);regular(target)
    if os.path.samefile(source,target):raise ValueError('source and target must differ')
    backup=target.with_name(target.name+'.previous')
    if os.path.lexists(backup):raise FileExistsError(str(backup))
    temporary=None;linked=False
    try:
        with source.open('rb') as src:
            fd,name=tempfile.mkstemp(prefix='.publish-',dir=target.parent)
            temporary=pathlib.Path(name)
            with os.fdopen(fd,'wb') as dst:shutil.copyfileobj(src,dst)
        subprocess.run(['setfacl','-b','--',str(temporary)],check=True)
        os.chmod(temporary,0o600)
        subprocess.run(['setfacl','-m',f'u:{reader_uid}:r--,m::r--','--',str(temporary)],check=True)
        os.link(target,backup);linked=True
        os.replace(temporary,target);temporary=None
    except BaseException:
        if temporary is not None:temporary.unlink(missing_ok=True)
        if linked:backup.unlink()
        raise
def rollback(target):
    target=pathlib.Path(target);backup=target.with_name(target.name+'.previous')
    regular(backup)
    os.replace(backup,target)
