import fcntl,os
def configure_alias(fd):
    alias=os.dup(fd)
    try:
        fcntl.fcntl(alias,fcntl.F_SETFD,fcntl.fcntl(alias,fcntl.F_GETFD)|fcntl.FD_CLOEXEC)
        fcntl.fcntl(alias,fcntl.F_SETFL,fcntl.fcntl(alias,fcntl.F_GETFL)|os.O_APPEND)
        return alias
    except BaseException:
        os.close(alias)
        raise

