import base64,hashlib,hmac,json,math,re

def _decode(segment):
    if not re.fullmatch(r'[A-Za-z0-9_-]+',segment) or len(segment)%4==1:
        raise ValueError('invalid base64url')
    raw=base64.urlsafe_b64decode(segment+'='*((-len(segment))%4))
    if base64.urlsafe_b64encode(raw).decode('ascii').rstrip('=')!=segment:
        raise ValueError('noncanonical base64url')
    return raw

def _pairs(pairs):
    result={}
    for key,value in pairs:
        if key in result:raise ValueError('duplicate JSON key')
        result[key]=value
    return result

def _constant(value):
    raise ValueError('non-JSON number')

def _float(value):
    number=float(value)
    if not math.isfinite(number):raise ValueError('nonfinite float')
    return number

def verify_signature(token,key):
    if not isinstance(token,str) or not token.isascii() or len(token)>8192:
        raise ValueError('invalid token')
    parts=token.split('.')
    if len(parts)!=3:raise ValueError('expected three segments')
    try:
        header=json.loads(_decode(parts[0]).decode('utf8'),object_pairs_hook=_pairs,parse_constant=_constant,parse_float=_float)
        payload=json.loads(_decode(parts[1]).decode('utf8'),object_pairs_hook=_pairs,parse_constant=_constant,parse_float=_float)
        signature=_decode(parts[2])
    except (UnicodeError,ValueError) as exc:
        raise ValueError('invalid encoding or JSON') from exc
    if not isinstance(header,dict) or not isinstance(payload,dict):raise ValueError('objects required')
    if header.get('alg')!='HS256' or 'crit' in header or 'b64' in header:raise ValueError('unsupported header')
    expected=hmac.new(key,(parts[0]+'.'+parts[1]).encode('ascii'),hashlib.sha256).digest()
    if len(signature)!=32 or not hmac.compare_digest(signature,expected):raise ValueError('bad signature')
    return payload
