import ctypes,hashlib,os,pathlib,stat,struct

class Watch:
    def __init__(self, directory):
        self.root=pathlib.Path(directory)
        libc=ctypes.CDLL(None,use_errno=True)
        libc.inotify_init1.argtypes=[ctypes.c_int]
        libc.inotify_init1.restype=ctypes.c_int
        libc.inotify_add_watch.argtypes=[ctypes.c_int,ctypes.c_char_p,ctypes.c_uint32]
        libc.inotify_add_watch.restype=ctypes.c_int
        self.fd=libc.inotify_init1(os.O_NONBLOCK|os.O_CLOEXEC)
        if self.fd<0:raise OSError(ctypes.get_errno(),'inotify_init1')
        if libc.inotify_add_watch(self.fd,os.fsencode(self.root),0x100|0x200|0x40|0x80|0x8)<0:
            error=ctypes.get_errno();os.close(self.fd);self.fd=-1
            raise OSError(error,'inotify_add_watch')

    def events(self):
        if self.fd<0:raise ValueError('watch closed')
        names=set()
        while True:
            try:data=os.read(self.fd,65536)
            except BlockingIOError:break
            except InterruptedError:continue
            if not data:break
            offset=0
            while offset<len(data):
                wd,mask,cookie,length=struct.unpack_from('iIII',data,offset)
                offset+=16
                name=data[offset:offset+length].split(b'\0',1)[0]
                offset+=length
                if name:names.add(os.fsdecode(name))
        return names

    def snapshot(self):
        if self.fd<0:raise ValueError('watch closed')
        result={}
        for entry in self.root.iterdir():
            if stat.S_ISREG(entry.lstat().st_mode):
                result[entry.name]=hashlib.sha256(entry.read_bytes()).hexdigest()
        return result

    def close(self):
        if self.fd>=0:
            os.close(self.fd);self.fd=-1
