import base64,hashlib,hmac,re

class Client:
    def __init__(self,state,nonce,verifier,exchange):
        if not isinstance(state,str) or not state or not isinstance(nonce,str) or not nonce:
            raise ValueError('state and nonce required')
        if not isinstance(verifier,str) or re.fullmatch(r'[A-Za-z0-9._~-]{43,128}',verifier) is None:
            raise ValueError('invalid verifier')
        self.state=state;self.nonce=nonce;self.verifier=verifier;self.exchange=exchange;self.used=False

    def request(self):
        challenge=base64.urlsafe_b64encode(hashlib.sha256(self.verifier.encode('ascii')).digest()).rstrip(b'=').decode('ascii')
        return {'state':self.state,'nonce':self.nonce,'code_challenge_method':'S256','code_challenge':challenge}

    def callback(self,state,code):
        if self.used or not isinstance(state,str) or state!=self.state or not isinstance(code,str) or not code:
            raise ValueError('callback rejected')
        self.used=True
        claims=self.exchange(code,self.verifier)
        if not isinstance(claims,dict) or claims.get('nonce')!=self.nonce:
            raise ValueError('nonce rejected')
        subject=claims.get('sub')
        if not isinstance(subject,str) or not subject:
            raise ValueError('subject rejected')
        return subject
```

