def repair_copy(source,destination):
    source=pathlib.Path(source).resolve();destination=pathlib.Path(destination).absolute()
    # Exclusive creation protects both a preexisting file and a hard-link alias.
    with source.open('rb') as inp,destination.open('xb') as out:
        shutil.copyfileobj(inp,out)
    env=dict(os.environ,LC_ALL='C')
    fixed=subprocess.run(['e2fsck','-f','-p',str(destination)],env=env,capture_output=True,timeout=8)
