from http.server import BaseHTTPRequestHandler
from http.cookies import SimpleCookie
import hmac

def make_handler(sessions,ledger):
    class Handler(BaseHTTPRequestHandler):
        def log_message(self,*args):pass
        def reply(self,status):
            self.send_response(status);self.send_header('Content-Length','0');self.end_headers()
        def do_GET(self):self.reply(405)
        def do_POST(self):
            if self.path!='/increment':self.reply(404);return
            raw=self.headers.get('Cookie','')
            try:
                jar=SimpleCookie();jar.load(raw)
                sid=jar['sid'].value if 'sid' in jar else ''
            except Exception:sid=''
            if sid not in sessions:self.reply(401);return
            token=self.headers.get('X-CSRF-Token','')
            if not token or not hmac.compare_digest(token.encode(),sessions[sid].encode()):
                self.reply(403);return
            with open(ledger,'ab') as stream:stream.write(sid.encode('ascii')+b'\n')
            self.reply(200)
    return Handler

