def make_record(password):
    salt=secrets.token_bytes(16)
    digest=hashlib.pbkdf2_hmac('sha256',password.encode('utf-8'),salt,10000,dklen=32)
    return 'pbkdf2-sha256$10000$'+salt.hex()+'$'+digest.hex()

def verify_record(password,record):
    if not isinstance(record,str):return False
    match=re.fullmatch(r'pbkdf2-sha256\$10000\$([0-9a-fA-F]{32})\$([0-9a-fA-F]{64})',record)
    if match is None:return False
    salt=bytes.fromhex(match.group(1));expected=bytes.fromhex(match.group(2))
    actual=hashlib.pbkdf2_hmac('sha256',password.encode('utf-8'),salt,10000,dklen=32)
    return hmac.compare_digest(actual,expected)

