import hashlib,json,os,pathlib,shutil,sqlite3,tempfile

def restore(root,now,rpo,output):
    root=pathlib.Path(root);output=pathlib.Path(output)
    if output.exists() or output.is_symlink():raise FileExistsError(output)
    catalog=json.loads((root/'catalog.json').read_text(encoding='utf-8'))
    choices=[x for x in catalog if x['at']<=now]
    if not choices:raise ValueError('no past recovery point')
    point=max(choices,key=lambda x:x['at'])
    if now-point['at']>rpo:raise ValueError('RPO not satisfied')
    source=root/point['directory'];manifest=json.loads((source/'manifest.json').read_text(encoding='utf-8'))
    if manifest['snapshot_id']!=point['id']:raise ValueError('manifest generation')
    db=source/'app.db'
    if not db.is_file() or db.is_symlink():raise ValueError('database file')
    if any((source/('app.db'+suffix)).exists() for suffix in ['-wal','-shm','-journal']):raise ValueError('not a self-contained backup')
    digest=lambda p:hashlib.sha256(p.read_bytes()).hexdigest()
    if digest(db)!=manifest['db_sha256']:raise ValueError('database digest')
    with sqlite3.connect(db.resolve().as_uri()+'?mode=ro',uri=True) as con:
        if con.execute('PRAGMA integrity_check').fetchall()!=[('ok',)]:raise ValueError('database integrity')
        if con.execute('SELECT snapshot_id FROM metadata').fetchall()!=[(point['id'],)]:raise ValueError('database generation')
        rows=con.execute('SELECT id,name,sha256 FROM uploads ORDER BY id').fetchall()
    expected={name:sha for _,name,sha in rows}
    if len(expected)!=len(rows) or expected!=manifest['objects']:raise ValueError('reference manifest mismatch')
    for name,sha in expected.items():
        if not isinstance(name,str) or name in ('','.','..') or '/' in name:raise ValueError('not a single object name')
        obj=source/'objects'/name
        if not obj.is_file() or obj.is_symlink() or digest(obj)!=sha:raise ValueError('missing or mixed object')
    stage=pathlib.Path(tempfile.mkdtemp(prefix='.restore-',dir=output.parent))
    try:
        shutil.copy2(db,stage/'app.db');(stage/'objects').mkdir()
        for name in expected:shutil.copy2(source/'objects'/name,stage/'objects'/name)
        os.rename(stage,output)
    finally:
        if stage.exists():shutil.rmtree(stage)
    return {'snapshot_id':point['id'],'age_seconds':now-point['at']}
