import base64,json,re,urllib.request
from cryptography.hazmat.primitives.asymmetric import rsa,padding
from cryptography.hazmat.primitives import hashes

def b64(text):
    if not isinstance(text,str) or not re.fullmatch(r'[A-Za-z0-9_-]+',text):raise ValueError('base64url')
    data=base64.urlsafe_b64decode(text+'='*((-len(text))%4))
    if base64.urlsafe_b64encode(data).rstrip(b'=').decode()!=text:raise ValueError('noncanonical encoding')
    return data

def unique(pairs):
    value={}
    for key,item in pairs:
        if key in value:raise ValueError('duplicate JSON key')
        value[key]=item
    return value

def load_keys(document):
    if not isinstance(document,dict) or not isinstance(document.get('keys'),list):raise ValueError('JWKS')
    result={}
    for item in document['keys']:
        if not isinstance(item,dict):raise ValueError('JWK')
        kid=item.get('kid')
        if not isinstance(kid,str) or not kid or kid in result:raise ValueError('ambiguous kid')
        if item.get('kty')!='RSA' or item.get('alg')!='RS256' or item.get('use')!='sig':raise ValueError('unsupported JWK')
        if 'key_ops' in item and item['key_ops']!=['verify']:raise ValueError('not a verification key')
        n=int.from_bytes(b64(item['n']),'big');e=int.from_bytes(b64(item['e']),'big')
        key=rsa.RSAPublicNumbers(e,n).public_key()
        if key.key_size<2048:raise ValueError('small training key')
        result[kid]=key
    return result

class NoRedirect(urllib.request.HTTPRedirectHandler):
    def redirect_request(self,req,fp,code,msg,headers,newurl):return None

class Verifier:
    def __init__(self,url,initial_jwks):
        self.url=url
        self.keys=load_keys(initial_jwks)

    def verify(self,token):
        try:
            head,body,signature=token.split('.')
            header=json.loads(b64(head),object_pairs_hook=unique)
            payload=json.loads(b64(body),object_pairs_hook=unique)
            if not isinstance(header,dict) or not isinstance(payload,dict):raise ValueError('JSON object required')
            if header.get('alg')!='RS256' or not isinstance(header.get('kid'),str) or not header['kid']:raise ValueError('header')
            if any(k in header for k in ['jku','jwk','x5u','x5c','crit']):raise ValueError('untrusted key/extension hint')
            sig=b64(signature);kid=header['kid']
            if kid not in self.keys:
                opener=urllib.request.build_opener(urllib.request.ProxyHandler({}),NoRedirect())
                with opener.open(self.url,timeout=2) as response:
                    raw=response.read(65537)
                if len(raw)>65536:raise ValueError('JWKS too large')
                candidate=load_keys(json.loads(raw,object_pairs_hook=unique))
                self.keys=candidate
            if kid not in self.keys:raise ValueError('still unknown kid')
            self.keys[kid].verify(sig,(head+'.'+body).encode('ascii'),padding.PKCS1v15(),hashes.SHA256())
            return payload
        except Exception as exc:
            raise ValueError('signature verification failed') from exc
