import math,os,select,time

def transfer(fd,payload,timeout):
    if not isinstance(payload,bytes):raise TypeError('payload must be bytes')
    if isinstance(timeout,bool) or not isinstance(timeout,(int,float)) or not math.isfinite(timeout) or timeout<0:raise ValueError('timeout')
    if not payload:return 0
    end=time.monotonic()+timeout;offset=0
    while offset<len(payload):
        remaining=end-time.monotonic()
        if remaining<=0:raise TimeoutError('pipe deadline')
        try:
            count=os.write(fd,payload[offset:])
            if count<=0:raise OSError('zero write')
            offset+=count
        except InterruptedError:continue
        except BlockingIOError:
            while True:
                remaining=end-time.monotonic()
                if remaining<=0:raise TimeoutError('pipe deadline')
                try:
                    if not select.select([], [fd], [], remaining)[1]:raise TimeoutError('pipe deadline')
                    break
                except InterruptedError:continue
    return offset
```

EAGAIN是当前容量不足，EPIPE是所有读端已关闭，必须分别处理；成功短写不是整批完成。monotonic总截止时间不会因为重试而重新计算，caller仍持有原FD。

[Linux pipe语义](https://man7.org/linux/man-pages/man7/pipe.7.html)

