def checked(result):
    if result<0:
        number=ctypes.get_errno();raise OSError(number,os.strerror(number))
    return result
def hexid(value):
    if not isinstance(value,str) or re.fullmatch(r'[0-9a-fA-F]{32}',value) is None:raise ValueError('16-byte hex identifier')
    return bytes.fromhex(value)

class Channel:
    def __init__(self,base,schema,epoch,create=False):
        if not isinstance(base,str) or re.fullmatch(r'[a-f0-9]{12}',base) is None:raise ValueError('base')
        if type(schema) is not int or schema not in (1,2):raise ValueError('schema')
        if type(create) is not bool:raise ValueError('create')
        epoch=hexid(epoch).hex();self.schema=schema;self.epoch=epoch
        self.name='/opsf-'+base+'-v'+str(schema)+'-'+epoch;self.fd=None;self.owner=create
        flags=os.O_RDWR|os.O_NONBLOCK|os.O_CLOEXEC
        if create:flags|=os.O_CREAT|os.O_EXCL
        fd=checked(lib.mq_open(self.name.encode(),flags,0o600,ctypes.byref(Attr(0,2,128,0)) if create else None))
        try:
