            if (attr.maxmsg,attr.msgsize)!=(2,128):raise ValueError('unknown queue attributes: preserve it')
        except BaseException:
            lib.mq_close(fd)
            if create:lib.mq_unlink(self.name.encode())
            raise
        self.fd=fd
    def _live(self):
        if self.fd is None:raise ValueError('closed channel')
        return self.fd
    def report(self):
        fd=self._live();attr=Attr();checked(lib.mq_getattr(fd,ctypes.byref(attr)))
        return dict(name=self.name,schema=self.schema,epoch=self.epoch,messages=attr.curmsgs,max_messages=attr.maxmsg,message_bytes=attr.msgsize,inode=os.fstat(fd).st_ino)
    def send(self,message_id,payload,priority=0):
        fd=self._live();identifier=hexid(message_id)
        if not isinstance(payload,bytes):raise TypeError('payload')
        if len(payload)>64:raise ValueError('payload too long')
        if type(priority) is not int or not 0<=priority<=7:raise ValueError('priority')
        packet=HEADER.pack(b'OPMQ',self.schema,bytes.fromhex(self.epoch),identifier,len(payload))+payload
        checked(lib.mq_send(fd,packet,len(packet),priority))
    def receive(self):
        fd=self._live();buf=ctypes.create_string_buffer(128);priority=ctypes.c_uint()
        count=lib.mq_receive(fd,buf,128,ctypes.byref(priority))
        if count<0 and ctypes.get_errno()==errno.EAGAIN:return None
        checked(count);raw=buf.raw[:count]
        bad=dict(status='quarantine',raw=raw,priority=priority.value)
        if len(raw)<HEADER.size or priority.value>7:return bad
        magic,schema,epoch,identifier,length=HEADER.unpack(raw[:HEADER.size])
        if magic!=b'OPMQ' or schema!=self.schema or epoch!=bytes.fromhex(self.epoch) or length>64 or len(raw)!=HEADER.size+length:return bad
        return dict(status='accepted',id=identifier.hex(),payload=raw[HEADER.size:],priority=priority.value)
    def retire(self):
        fd=self._live()
        if not self.owner:raise PermissionError('only the coordinator that created this queue may retire it')
        # Coordinator serializes retirement/recreation and has stopped producers.
        other=lib.mq_open(self.name.encode(),os.O_RDWR|os.O_NONBLOCK|os.O_CLOEXEC,0,None)
        if other<0 and ctypes.get_errno()==errno.ENOENT:return False
        checked(other)
        try:
            if os.fstat(other).st_ino!=os.fstat(fd).st_ino:raise RuntimeError('name now belongs to a different queue instance')
        finally:checked(lib.mq_close(other))
        if self.report()['messages']:raise BlockingIOError(errno.EAGAIN,'drain pending work before retirement')
        checked(lib.mq_unlink(self.name.encode()));return True
    def close(self):
        if self.fd is not None:
            fd=self.fd;self.fd=None;checked(lib.mq_close(fd))
