import pathlib,re,subprocess
ALLOWED={'vm.swappiness','kernel.pid_max','fs.file-max'}
ASSIGN=re.compile(r'^(\s*([a-z0-9_.-]+)\s*=\s*)([0-9]+)([ \t]*(?:#.*)?)(\n?)$')

def reconcile(path,keys):
    keys=list(keys)
    if len(set(keys))!=len(keys) or any(key not in ALLOWED for key in keys):raise ValueError('unsupported or repeated key')
    current={}
    for key in keys:
