        if not re.fullmatch(r'[0-9]+',value):raise ValueError('unexpected kernel value')
        current[key]=value
    target=pathlib.Path(path);original=target.read_bytes().decode('utf8');lines=[];seen=set()
    for line in original.splitlines(keepends=True):
        match=ASSIGN.fullmatch(line)
        if match and match[2] in current:
            seen.add(match[2]);line=match[1]+current[match[2]]+match[4]+match[5]
        lines.append(line)
    output=''.join(lines)
    for key in keys:
        if key not in seen:
            if output and not output.endswith('\n'):output+='\n'
            output+=key+' = '+current[key]+'\n'
    target.write_bytes(output.encode('utf8'))
